const normalized = $('Normalize Dataset').item.json;
const errors = $json.validation?.errors || $json.ai_validation?.errors || ['unknown_client_error'];
return { json: {
  report_key: normalized.meta.report_key,
  client_id: normalized.client.id,
  period_start: normalized.reporting_period.start,
  period_end: normalized.reporting_period.end,
  status: 'DATA_ERROR',
  reviewer: normalized.client.reviewer_email,
  approved_at: '',
  sent_at: '',
  recipient: normalized.client.recipient_email,
  execution_id: $execution.id,
  error_message: errors.join(', ').slice(0, 500)
} };

const input = $json;
const config = $('Configure Report Template').first().json;
const timezone = input.timezone || 'UTC';
let periodEndText = String(input.period_end || '').trim();
let timezoneValid = true;
try {
 const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date(config.run_started_at)).filter(p => ['year','month','day'].includes(p.type)).map(p => [p.type,p.value]));
 if (!periodEndText) { const date = new Date(parts.year + '-' + parts.month + '-' + parts.day + 'T00:00:00Z'); date.setUTCDate(date.getUTCDate() - ((date.getUTCDay() + 6) % 7) - 1); periodEndText = date.toISOString().slice(0,10); }
} catch { timezoneValid = false; }
const end = new Date(periodEndText + 'T00:00:00Z');
const validEnd = timezoneValid && /^\d{4}-\d{2}-\d{2}$/.test(periodEndText) && Number.isFinite(end.getTime()) && end.toISOString().slice(0,10) === periodEndText;
const shift = days => { const date = new Date(end); date.setUTCDate(date.getUTCDate() + days); return date.toISOString().slice(0,10); };
return { json: { ...input, period_start: validEnd ? shift(-6) : '', period_end: validEnd ? periodEndText : '', comparison_start: validEnd ? shift(-13) : '', comparison_end: validEnd ? shift(-7) : '', period_valid: validEnd, data_as_of: config.run_started_at, test_mode: false } };

if ($json.demo_dataset) return { json: $json.demo_dataset };
const state = $('Attach Current Ads').item.json;
const previousRow = $json || {};
const previousMatch = previousRow.client_id === state.client_id
  && previousRow.period_type === 'PREVIOUS'
  && String(previousRow.period_start || '') === state.comparison_start
  && String(previousRow.period_end || '') === state.comparison_end;
const context = state.context_row;
const current = state.current_ads;
const previous = previousMatch ? previousRow : null;
const list = (value) => String(value || '').split(';').map(x => x.trim()).filter(Boolean);
const metrics = (row) => row ? {
  spend: row.spend,
  conversions: row.conversions,
  clicks: row.clicks,
  conversion_rate: row.conversion_rate,
  cost_per_conversion: row.cost_per_conversion
} : null;
return {
  json: {
    client: {
      id: state.client_id,
      name: state.client_name,
      google_ads_customer_id: state.google_ads_customer_id,
      recipient_email: state.recipient_email,
      reviewer_email: state.reviewer_email,
      timezone: state.timezone,
      currency: state.currency,
      reporting_day: state.reporting_day
    },
    reporting_period: { start: state.period_start, end: state.period_end },
    comparison_period: { start: state.comparison_start, end: state.comparison_end },
    metrics: { current: metrics(current), previous: metrics(previous) },
    ads_rows: { current, previous },
    context: {
      completed_work: context ? list(context.completed_work) : [],
      blockers: context ? list(context.blockers) : [],
      client_requests: context ? list(context.client_requests) : [],
      next_actions: context ? list(context.next_actions) : [],
      internal_notes: context ? String(context.internal_notes || '') : ''
    },
    lookup: {
      context_found: Boolean(context),
      current_ads_found: Boolean(current),
      previous_ads_found: Boolean(previous)
    },
    meta: {
      data_as_of: state.data_as_of,
      report_key: state.report_key,
      execution_id: $execution.id
    },
    test_mode: false,
    mock_approval_decision: state.mock_approval_decision,
    period_valid: state.period_valid
  }
};

const data = $json;
const errors = [];
const isNumber = v => typeof v === 'number' && Number.isFinite(v);
const isISO = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) && Number.isFinite(Date.parse(v + 'T00:00:00Z')) && new Date(v + 'T00:00:00Z').toISOString().slice(0,10) === v;
const days = (a, b) => (Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000;
const close = (a, b, tolerance) => isNumber(a) && isNumber(b) && Math.abs(a - b) <= tolerance;
if (!data.client?.id) errors.push('missing_client_id');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.client?.recipient_email || '')) errors.push('missing_recipient_email');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.client?.reviewer_email || '')) errors.push('missing_reviewer_email');
if (!data.period_valid) errors.push('invalid_explicit_period_end');
const rs = data.reporting_period?.start, re = data.reporting_period?.end;
const cs = data.comparison_period?.start, ce = data.comparison_period?.end;
if (!isISO(rs) || !isISO(re) || days(rs, re) !== 6) errors.push('reporting_period_not_7_days');
if (!isISO(cs) || !isISO(ce) || days(cs, ce) !== 6) errors.push('comparison_period_not_7_days');
if (isISO(ce) && isISO(rs) && days(ce, rs) !== 1) errors.push('comparison_not_immediately_previous');
if (!data.lookup?.context_found) errors.push('missing_weekly_context');
if (!data.lookup?.current_ads_found) errors.push('missing_current_ads');
if (!data.lookup?.previous_ads_found) errors.push('missing_previous_ads');
for (const period of ['current', 'previous']) {
  const row = data.ads_rows?.[period];
  const m = data.metrics?.[period];
  if (!row || !m) continue;
  if (row.client_id !== data.client.id) errors.push(period + '_ads_wrong_client');
  if (row.source !== 'sheet') errors.push(period + '_ads_source_not_sheet');
  for (const field of ['spend','conversions','clicks','conversion_rate','cost_per_conversion']) {
    if (!isNumber(m[field])) errors.push(period + '_' + field + '_not_number');
    else if (m[field] < 0) errors.push(period + '_' + field + '_negative');
  }
  if (isNumber(m.conversion_rate) && m.conversion_rate > 1) errors.push(period + '_conversion_rate_above_one');
  if (m.clicks === 0 && m.conversion_rate !== 0) errors.push(period + '_zero_click_rate_inconsistent');
  if (m.conversions === 0 && m.cost_per_conversion !== 0) errors.push(period + '_zero_conversion_cost_inconsistent');
  if (isNumber(m.clicks) && !Number.isInteger(m.clicks)) errors.push(period + '_clicks_not_integer');
  if (isNumber(m.conversions) && !Number.isInteger(m.conversions)) errors.push(period + '_conversions_not_integer');
  if (isNumber(m.clicks) && isNumber(m.conversions) && m.conversions > m.clicks) errors.push(period + '_conversions_exceed_clicks');
  if (isNumber(m.clicks) && isNumber(m.conversions) && m.clicks > 0 && !close(m.conversion_rate, m.conversions / m.clicks, 0.0001)) errors.push(period + '_conversion_rate_inconsistent');
  if (isNumber(m.spend) && isNumber(m.conversions) && m.conversions > 0 && !close(m.cost_per_conversion, m.spend / m.conversions, 0.02)) errors.push(period + '_cost_per_conversion_inconsistent');
}
if (!Array.isArray(data.context?.completed_work) || data.context.completed_work.length === 0) errors.push('missing_completed_work');
if (!Array.isArray(data.context?.next_actions) || data.context.next_actions.length === 0) errors.push('missing_next_actions');
return { json: { ...data, validation: { valid: errors.length === 0, errors } } };

const data = $json;
const calc = (current, previous) => {
  if (previous === 0 && current === 0) return { absolute_change: 0, change_pct: 0, change_label: null };
  if (previous === 0) return { absolute_change: current, change_pct: null, change_label: 'new activity' };
  return { absolute_change: current - previous, change_pct: ((current - previous) / previous) * 100, change_label: null };
};
const c = data.metrics.current, p = data.metrics.previous;
return { json: { ...data, changes: {
  spend: calc(c.spend,p.spend),
  conversions: calc(c.conversions,p.conversions),
  clicks: calc(c.clicks,p.clicks),
  conversion_rate: calc(c.conversion_rate,p.conversion_rate),
  cost_per_conversion: calc(c.cost_per_conversion,p.cost_per_conversion)
} } };

const data = $json;
const round1 = n => typeof n === 'number' ? Math.round(n * 10) / 10 : n;
const fact = (key) => ({
  current: data.metrics.current[key],
  previous: data.metrics.previous[key],
  change_pct: round1(data.changes[key].change_pct),
  change_label: data.changes[key].change_label
});
return { json: {
  client_id: data.client.id,
  client_name: data.client.name,
  currency: data.client.currency,
  period_start: data.reporting_period.start,
  period_end: data.reporting_period.end,
  data_as_of: data.meta.data_as_of,
  verified_metrics: {
    spend: fact('spend'),
    conversions: fact('conversions'),
    clicks: fact('clicks'),
    conversion_rate: fact('conversion_rate'),
    cost_per_conversion: fact('cost_per_conversion')
  },
  completed_work: data.context.completed_work,
  blockers: data.context.blockers,
  client_requests: data.context.client_requests,
  next_actions: data.context.next_actions,
  meta: { report_key: data.meta.report_key }
} };

const response = $json || {};
let raw = response.content?.parts?.[0]?.text || response.candidates?.[0]?.content?.parts?.[0]?.text || response.text || response.output || '';
let draft = null; const errors = [];
try { draft = typeof raw === 'object' ? raw : JSON.parse(String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')); } catch { errors.push('invalid_ai_json'); }
if (!draft || typeof draft !== 'object' || Array.isArray(draft)) errors.push('ai_output_must_be_object');
else {
 if (Object.keys(draft).length !== 1 || !Object.hasOwn(draft,'summary')) errors.push('unexpected_ai_fields');
 if (typeof draft.summary !== 'string' || !draft.summary.trim()) errors.push('missing_summary');
 else {
  if (draft.summary.trim().split(/\s+/).length > 100) errors.push('summary_too_long');
  if (/[\p{N}]/u.test(draft.summary) || /\b(?:zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|twenty|thirty|forty|fifty|hundred|thousand|million|billion)\b/i.test(draft.summary)) errors.push('summary_must_not_contain_numbers');
 }
}
return { json: { draft, ai_validation: { valid: errors.length === 0, errors } } };

const facts = $('Build Verified Facts').item.json;
const data = $('Normalize Dataset').item.json;
const config = $('Configure Report Template').first().json;
const escape = value => String(value ?? '').replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const list = values => values.length ? '<ul>' + values.map(value => '<li>' + escape(value) + '</li>').join('') + '</ul>' : '<p>None recorded.</p>';
const format = (key, value) => key === 'conversion_rate' ? (value * 100).toFixed(2) + '%' : ['spend','cost_per_conversion'].includes(key) ? value.toFixed(2) + ' ' + escape(facts.currency) : String(value);
const rows = Object.entries(facts.verified_metrics).map(([key, metric]) => '<tr><td>' + escape(key.replaceAll('_',' ')) + '</td><td>' + format(key,metric.current) + '</td><td>' + format(key,metric.previous) + '</td><td>' + (metric.change_pct === null ? 'New activity' : metric.change_pct.toFixed(1) + '%') + '</td></tr>').join('');
const emailSubject = data.client.name + ' — Weekly update | ' + facts.period_start + ' to ' + facts.period_end;
const emailHtml = '<p>Hi,</p><p>Weekly update for ' + escape(data.client.name) + '.</p><p>' + escape($json.draft.summary) + '</p><h3>Verified performance</h3><table border="1" cellpadding="6"><tr><th>Metric</th><th>Current</th><th>Previous</th><th>Change</th></tr>' + rows + '</table><h3>Completed work</h3>' + list(facts.completed_work) + '<h3>Blockers</h3>' + list(facts.blockers) + '<h3>Next actions</h3>' + list(facts.next_actions) + '<h3>Need from you</h3>' + list(facts.client_requests) + '<p>Data period: ' + escape(facts.period_start) + ' to ' + escape(facts.period_end) + '.</p><p>Best,<br>' + escape(config.sender_name) + '</p>';
return { json: { ...facts, client_id:data.client.id, client_name:data.client.name, reviewer_email:data.client.reviewer_email, recipient_email:data.client.recipient_email, report_key:data.meta.report_key, email_subject:emailSubject, email_html:emailHtml, reviewer_preview_html:"<p>Recipient: " + escape(data.client.recipient_email) + "</p><p>Subject: " + escape(emailSubject) + "</p><hr>" + emailHtml, test_mode:data.test_mode } };

const review = $json;
return { json: {
  report_key: review.report_key, client_id: review.client_id, period_start: review.period_start, period_end: review.period_end,
  status: 'REJECTED', reviewer: review.reviewer_email, approved_at: '', sent_at: '',
  recipient: review.recipient_email, execution_id: $execution.id, error_message: '', email_subject:review.email_subject, email_html:review.email_html, gmail_message_id:''
} };

const review = $json;
return { json: {
  report_key: review.report_key, client_id: review.client_id, period_start: review.period_start, period_end: review.period_end,
  status: 'APPROVAL_TIMEOUT', reviewer: review.reviewer_email, approved_at: '', sent_at: '',
  recipient: review.recipient_email, execution_id: $execution.id, error_message: 'approval_window_expired', email_subject:review.email_subject, email_html:review.email_html, gmail_message_id:''
} };

return $input.all().filter(item => {
  const value = item.json.active;
  return value === true || String(value).trim().toUpperCase() === 'TRUE';
});

const current = $('Build Report Key').item.json;
const row = $json || {};
const found = Boolean(row.report_key) && row.report_key === current.report_key;
return {
  json: {
    ...current,
    report_found: found,
    existing_status: found ? String(row.status || '').trim() : ''
  }
};

const state = $('Classify Report State').item.json;
const row = $json || {};
const match = row.client_id === state.client_id
  && String(row.period_start || '') === state.period_start
  && String(row.period_end || '') === state.period_end;
return { json: { ...state, context_row: match ? row : null } };

const state = $('Attach Context').item.json;
const row = $json || {};
const match = row.client_id === state.client_id
  && row.period_type === 'CURRENT'
  && String(row.period_start || '') === state.period_start
  && String(row.period_end || '') === state.period_end;
return { json: { ...state, current_ads: match ? row : null } };

const review = $('Format Internal Review').item.json;
const state = $json.data?.approved === true ? 'approved' : $json.data?.approved === false ? 'rejected' : 'timeout';
return { json: { ...review, approval_state:state, approved_at: state === 'approved' ? $now.toISO() : '' } };

// Demo mode makes no external calls. Set false only after controlled setup/testing.
const config = { test_mode: true, spreadsheet_id: 'YOUR_SPREADSHEET_ID', sender_name: 'Your reporting team', run_started_at: $now.toISO() };
if (!config.test_mode && (!config.spreadsheet_id || config.spreadsheet_id.startsWith('YOUR_'))) throw new Error('Configure spreadsheet_id before live mode.');
return { json: config };
